    "표8_상담적용": [
        {"상황":"믿었던 사람에게 배신당해 깊은 상처를 받은 분", "성경원리":"예루살렘도 사랑하던 자들과 친구들에게 배반을 당했다. 그러나 하나님은 결코 배반하지 않으신다 (신 31:8)", "실제적용":"인간의 배신을 하나님의 신실함을 더 깊이 경험하는 기회로 삼으라. 상처받은 마음을 하나님께 솔직히 가져오라"},
        {"상황":"밤마다 잠 못 이루고 눈물로 지새우는 분", "성경원리":"하나님은 우리의 밤 눈물을 보시고 병에 담으신다 (시 56:8). 밤의 통곡도 하나님은 들으신다", "실제적용":"잠 못 드는 밤을 기도의 시간으로 전환하라. 눈물로 드리는 기도가 가장 진실한 기도다"},
        {"상황":"주변에 아무도 없다는 극심한 외로움을 느끼는 분", "성경원리":"'위로하는 자가 없고'의 절망적 고독도 하나님 앞에 드려지면 기도가 된다", "실제적용":"외로움을 하나님을 만나는 공간으로 허용하라. 하나님은 고독한 자의 아버지 되신다 (시 68:5-6)"}
    ],
    "표9_교차참조": [
        {"구절":"시 56:8", "연결점":"하나님이 나그네 생활의 눈물을 병에 담으심 - 하나님은 눈물을 기억하신다", "구분":"구약"},
        {"구절":"시 6:6", "연결점":"밤마다 눈물로 침상을 적신다는 다윗의 통곡 - 동일한 밤의 슬픔", "구분":"구약"},
        {"구절":"옵 1:10-14", "연결점":"에돔이 형제 이스라엘의 재난 날에 방관하고 기뻐함 - 친구의 배반", "구분":"구약"},
        {"구절":"미 7:5-6", "연결점":"친구를 믿지 말라, 이웃을 의지하지 말라 - 인간 신의의 한계", "구분":"구약"},
        {"구절":"마 26:47-50", "연결점":"유다가 입맞춤으로 예수님을 배반함 - 가장 가까운 자의 배신", "구분":"신약"},
        {"구절":"요 16:20", "연결점":"너희는 울고 애통하겠으나 세상은 기뻐하리라 - 고난의 때에 외로운 제자들", "구분":"신약"},
        {"구절":"고후 1:3-4", "연결점":"모든 위로의 하나님 - 우리의 모든 환난 중에 위로하심", "구분":"신약"},
        {"구절":"계 21:4", "연결점":"하나님이 모든 눈물을 씻어주심 - 통곡의 완전한 종결", "구분":"신약"}
    ]
