    "표8_상담적용": [
        {"상황":"내면의 극심한 고통으로 신체화 증상(두통, 위장 장애 등)을 경험하는 분", "성경원리":"창자가 끊기고 심장이 뒤집히는 신체적 표현이 내면 고통의 신체화를 보여준다. 하나님은 이 신체적 고통까지도 보고 아신다", "실제적용":"신체적 증상도 하나님께 가져오라. 내면의 고통을 해결할 때 신체적 증상도 치유된다. 전인적 치유를 하나님께 구하라"},
        {"상황":"외부적 위협(직장, 관계, 재정)과 내부적 고통(불안, 우울)이 동시에 압박하는 분", "성경원리":"'밖에는 칼, 안에는 죽음' - 이 이중 위협을 아시는 하나님이 계신다", "실제적용":"한 번에 다 해결하려 하지 말라. '여호와여 보옵소서'라는 한 마디 기도로 시작하라. 하나님이 보시면 해결이 시작된다"},
        {"상황":"점점 더 깊어지는 죄책감과 수치심으로 힘들어하는 분", "성경원리":"더 깊은 위기 앞에서 더 깊은 고백이 나왔다. 더 깊은 고백이 더 깊은 회복을 이끈다", "실제적용":"죄책감을 방어하지 말고 더 깊이 하나님 앞에 가져가라. 깊은 고백이 깊은 용서와 치유를 부른다 (요일 1:9)"}
    ],
    "표9_교차참조": [
        {"구절":"렘 31:20", "연결점":"하나님이 에브라임을 향해 창자가 끊긴다고 하심 - 하나님도 창자가 끊기는 연민을 느끼심", "구분":"구약"},
        {"구절":"렘 14:18", "연결점":"들에는 칼, 성안에는 기근 - 1:20의 밖에는 칼 안에는 죽음의 역사적 배경", "구분":"구약"},
        {"구절":"시 139:1-4", "연결점":"주께서 나를 감찰하시고 아신다 - 가장 깊은 내면도 아시는 하나님", "구분":"구약"},
        {"구절":"호 14:1-2", "연결점":"이스라엘아 네 하나님 여호와께 돌아오라 - 배역 고백 후의 회개 촉구", "구분":"구약"},
        {"구절":"마 26:38", "연결점":"심히 고민하여 죽게 되었다는 겟세마네의 예수님 - 창자가 끊기는 고통의 공유", "구분":"신약"},
        {"구절":"롬 8:26", "연결점":"말할 수 없는 탄식으로 우리를 위해 간구하시는 성령 - 창자가 끊기는 기도", "구분":"신약"},
        {"구절":"히 4:15", "연결점":"우리의 모든 연약함에 동정하시는 대제사장 - 내면 고통을 아시는 그리스도", "구분":"신약"},
        {"구절":"마 26:44", "연결점":"세 번 기도하신 예수님 - 반복 기도의 모범", "구분":"신약"}
    ]
